#!/usr/bin/env python3
"""Instala ou atualiza o projeto BXbox Cloud TV na raiz do repositório atual."""
import argparse,base64,hashlib,io,zipfile
from pathlib import Path
parser=argparse.ArgumentParser(description=__doc__)
parser.add_argument('--sem-workflow',action='store_true',help='manter o workflow atual e editar pelo GitHub se necessário')
parser.add_argument('--substituir',action='store_true',help='substituir arquivos do projeto; revise alterações próprias antes de usar')
args=parser.parse_args()
DATA=""""""
data=base64.b64decode(DATA)
assert hashlib.sha256(data).hexdigest()=="b01bb7440bbe11570c7d1aef92fd547896a7727021f90bf88dbba5637af64126", "Instalador alterado"
root=Path.cwd().resolve()
with zipfile.ZipFile(io.BytesIO(data)) as archive:
    items=[]
    for info in archive.infolist():
        path=Path(info.filename)
        if args.sem_workflow and path.parts[0]=='.github':continue
        target=(root/path).resolve()
        if path.is_absolute() or root not in target.parents:raise SystemExit('Caminho inválido')
        body=archive.read(info)
        if target.exists() and target.read_bytes()!=body and not args.substituir:raise SystemExit(f'{path} já existe. Para atualizar o projeto, revise suas mudanças e use --substituir.')
        items.append((target,body))
    # Migração da versão 0.1: o banner XML foi substituído por PNG.
    old=(root/'app/src/main/res/drawable/banner.xml').resolve()
    if root not in old.parents:raise SystemExit('Caminho de migração inválido')
    if old.is_file():
        if not args.substituir:raise SystemExit('Há um banner antigo. Use --substituir para migrar.')
        old.unlink()
    for target,body in items:
        target.parent.mkdir(parents=True,exist_ok=True)
        target.write_bytes(body)
(root/'gradlew').chmod(0o755)
print(f'Pronto: BXbox Cloud TV 0.2.0, {len(items)} arquivos gravados.')
print('Revise as mudanças e execute git add ., git commit e git push, conforme o guia.')
